export type CatalogExercise = {
  id: string;            // id de RepDB (también nombre de sus imágenes)
  name: string;          // español
  en: string;            // inglés (solo para buscar)
  group: Group;          // grupo principal (el primero de "groups")
  groups: Group[];       // grupos primarios
  secondary: Group[];    // grupos secundarios
  equipment: Equipment;
  kind: Kind;
  grips?: Grip[];        // variantes de agarre (etiqueta + id del ejercicio equivalente)
};

